// Outfit and skin textures, painted in body coordinates.
//
// The humanoid build gives every body and clothing shell the same positional
// UV atlas (see ATLAS in humanoid.mjs): the left half of the image is the
// front of the body, the right half the back, both seen in bind pose (T-pose).
// So a texture can be drawn as vector art using metres on the body — "a seam
// at chest height" — and it lands in the same place on any body shape.
//
// These are original works generated by this file; no third-party art is used.

import sharp from 'sharp';
import { ATLAS } from './humanoid.mjs';

const S = 1024;
const fx = (x) => ((0.25 + (x / ATLAS.halfWidthM) * 0.25) * S).toFixed(1); // front half
const bx = (x) => ((0.75 - (x / ATLAS.halfWidthM) * 0.25) * S).toFixed(1); // back half
const py = (y) => ((1 - y / ATLAS.heightM) * S).toFixed(1);

/** Path through body-space points [x, y]; `side` picks the front or back half. */
function path(points, side, attrs) {
  const X = side === 'back' ? bx : fx;
  const d = points.map(([x, y], i) => `${i ? 'L' : 'M'}${X(x)} ${py(y)}`).join(' ');
  return `<path d="${d}" fill="none" stroke-linecap="round" stroke-linejoin="round" ${attrs}/>`;
}
/** Smooth curve through points (quadratic through midpoints). */
function curve(points, side, attrs) {
  const X = side === 'back' ? bx : fx;
  let d = `M${X(points[0][0])} ${py(points[0][1])}`;
  for (let i = 1; i < points.length - 1; i++) {
    const mx = (points[i][0] + points[i + 1][0]) / 2;
    const my = (points[i][1] + points[i + 1][1]) / 2;
    d += ` Q${X(points[i][0])} ${py(points[i][1])} ${X(mx)} ${py(my)}`;
  }
  const last = points[points.length - 1];
  d += ` L${X(last[0])} ${py(last[1])}`;
  return `<path d="${d}" fill="none" stroke-linecap="round" stroke-linejoin="round" ${attrs}/>`;
}
const mirror = (points) => points.map(([x, y]) => [-x, y]);
/** Draw on both sides of the body's centre line. */
const both = (draw, points, side, attrs) => draw(points, side, attrs) + draw(mirror(points), side, attrs);
/** Rectangle spanning body-space x0..x1, y0..y1 on one half. */
function rect(x0, x1, y0, y1, side, attrs) {
  const X = side === 'back' ? bx : fx;
  const a = Number(X(x0));
  const b = Number(X(x1));
  return `<rect x="${Math.min(a, b)}" y="${py(y1)}" width="${Math.abs(b - a)}" height="${Number(py(y0)) - Number(py(y1))}" ${attrs}/>`;
}
const svg = (body, background) => `<svg xmlns="http://www.w3.org/2000/svg" width="${S}" height="${S}" viewBox="0 0 ${S} ${S}"><rect width="${S}" height="${S}" fill="${background}"/>${body}</svg>`;

// --- Red Rucker ----------------------------------------------------------------
// Flat crimson with inked muscle definition, after the owner's illustrations:
// collarbones, pectorals, a six-part abdomen, serratus, and on the back the
// spine, shoulder blades and lats. No facial features.

function redRuckerBody() {
  const shade = 'stroke="#7c0f14" stroke-opacity="0.62" stroke-width="3.2"';
  const thin = 'stroke="#7c0f14" stroke-opacity="0.5" stroke-width="2.2"';
  const light = 'stroke="#ff5a4e" stroke-opacity="0.4" stroke-width="5"';
  let g = '';
  // Soft form shading on the flanks.
  g += both(curve, [[0.165, 1.4], [0.15, 1.2], [0.13, 1.02]], 'front', 'stroke="#8f1218" stroke-opacity="0.3" stroke-width="16"');
  // Front torso.
  g += both(curve, [[0.02, 1.455], [0.09, 1.47], [0.17, 1.455]], 'front', shade); // collarbones
  g += both(curve, [[0.012, 1.32], [0.05, 1.262], [0.115, 1.262], [0.165, 1.31], [0.175, 1.37]], 'front', shade); // pectoral lower edge
  g += path([[0, 1.42], [0, 1.27]], 'front', thin); // sternum
  g += path([[0, 1.24], [0, 1.0]], 'front', shade); // linea alba
  for (const y of [1.195, 1.135, 1.075]) g += both(curve, [[0.006, y], [0.04, y - 0.006], [0.078, y + 0.004]], 'front', thin); // abdominal bands
  g += both(curve, [[0.085, 1.245], [0.098, 1.14], [0.088, 1.03], [0.06, 0.975]], 'front', shade); // rectus outer edge
  for (const y of [1.215, 1.17, 1.125]) g += both(path, [[0.105, y], [0.14, y + 0.022]], 'front', thin); // serratus
  g += both(curve, [[0.13, 1.0], [0.09, 0.955], [0.03, 0.93]], 'front', thin); // iliac line
  g += both(curve, [[0.05, 1.3], [0.1, 1.33], [0.15, 1.34]], 'front', light); // chest highlight
  // Arms (horizontal in bind pose): deltoid cap, biceps and forearm lines.
  g += both(curve, [[0.2, 1.4], [0.235, 1.43], [0.25, 1.485]], 'front', shade);
  g += both(curve, [[0.27, 1.418], [0.36, 1.405], [0.45, 1.42]], 'front', thin);
  g += both(curve, [[0.5, 1.42], [0.6, 1.41], [0.7, 1.425]], 'front', thin);
  // Legs: quadriceps sweep, kneecap, shin.
  g += both(curve, [[0.07, 0.86], [0.1, 0.72], [0.085, 0.6]], 'front', thin);
  g += both(curve, [[0.055, 0.565], [0.089, 0.585], [0.123, 0.565]], 'front', shade);
  g += both(curve, [[0.06, 0.5], [0.089, 0.485], [0.12, 0.5]], 'front', thin);
  g += both(path, [[0.085, 0.46], [0.09, 0.2]], 'front', thin);
  // Head: only the faint brow and jaw planes of the illustrations — no face.
  g += curve([[-0.055, 1.705], [0, 1.69], [0.055, 1.705]], 'front', 'stroke="#7c0f14" stroke-opacity="0.28" stroke-width="5"');
  g += curve([[-0.05, 1.6], [0, 1.578], [0.05, 1.6]], 'front', 'stroke="#7c0f14" stroke-opacity="0.3" stroke-width="3"');
  // Back.
  g += path([[0, 1.45], [0, 1.0]], 'back', shade); // spine
  g += both(curve, [[0.03, 1.4], [0.09, 1.36], [0.12, 1.29], [0.07, 1.26]], 'back', shade); // shoulder blades
  g += both(curve, [[0.16, 1.36], [0.15, 1.22], [0.1, 1.08], [0.05, 1.02]], 'back', shade); // lats
  g += both(curve, [[0.02, 1.5], [0.09, 1.47], [0.18, 1.45]], 'back', thin); // trapezius
  g += both(curve, [[0.03, 0.98], [0.1, 0.9], [0.15, 0.93]], 'back', thin); // glute line
  g += both(curve, [[0.06, 0.45], [0.095, 0.36], [0.085, 0.25]], 'back', shade); // calf
  g += both(curve, [[0.065, 0.8], [0.09, 0.68], [0.08, 0.58]], 'back', thin); // hamstring
  g += both(curve, [[0.27, 1.46], [0.36, 1.47], [0.45, 1.455]], 'back', thin); // triceps
  return svg(g, '#d0211f');
}

function redRuckerShorts() {
  const seam = 'stroke="#4e0b10" stroke-opacity="0.8" stroke-width="2.5"';
  let g = '';
  for (const side of ['front', 'back']) {
    g += rect(-0.3, 0.3, 0.985, 1.05, side, 'fill="#5c0e13"'); // waistband
    g += path([[-0.3, 0.985], [0.3, 0.985]], side, seam);
    g += rect(-0.3, 0.3, 0.55, 0.6, side, 'fill="#681015"'); // hem band
    g += path([[0, 0.985], [0, 0.86]], side, seam); // rise seam
    g += both(path, [[0.165, 0.985], [0.17, 0.58]], side, seam); // side seams
    g += both(curve, [[0.04, 0.95], [0.1, 0.85], [0.12, 0.7]], side, 'stroke="#a3222a" stroke-opacity="0.35" stroke-width="7"'); // fold highlight
  }
  // "RED RUCKER" along the hem of the left leg, as on the reference shorts.
  g += `<text x="${fx(0.115)}" y="${py(0.607)}" font-family="DejaVu Sans, Arial, sans-serif" font-weight="700" font-size="11" fill="#f4f1ea" text-anchor="middle" transform="scale(0.55,1)" transform-origin="${fx(0.115)} ${py(0.607)}">RED RUCKER</text>`;
  return svg(g, '#7d1519');
}

// --- class outfits ---------------------------------------------------------------

/** Armour plating: panel seams and edge wear, multiplied over the plate colour. */
function platePanels() {
  const seam = 'stroke="#000" stroke-opacity="0.55" stroke-width="2.4"';
  const edge = 'stroke="#fff" stroke-opacity="0.22" stroke-width="2"';
  let g = '';
  for (const side of ['front', 'back']) {
    g += path([[0, 1.46], [0, 1.16]], side, seam);
    g += both(path, [[0.03, 1.4], [0.15, 1.36], [0.17, 1.26], [0.06, 1.2]], side, seam);
    g += both(path, [[0.035, 1.39], [0.145, 1.352]], side, edge);
    for (const y of [1.13, 1.07]) g += path([[-0.2, y], [0.2, y]], side, seam);
    g += both(path, [[0.5, 1.5], [0.5, 1.38]], side, seam) + both(path, [[0.62, 1.5], [0.62, 1.38]], side, seam);
    g += both(path, [[0.04, 0.42], [0.14, 0.42]], side, seam) + both(path, [[0.04, 0.26], [0.14, 0.26]], side, seam);
    g += both(path, [[0.089, 0.5], [0.089, 0.14]], side, edge);
    g += path([[-0.1, 1.74], [0.1, 1.74]], side, seam);
  }
  return svg(g, '#c9c9c9');
}

/** Emissive strips for the Vanguard's storage plates (amber on black). */
function plateGlow() {
  const strip = 'stroke="#ffb45c" stroke-width="4.5"';
  let g = '';
  g += both(path, [[0.045, 1.25], [0.12, 1.285]], 'front', strip);
  g += both(path, [[0.52, 1.445], [0.6, 1.445]], 'front', strip) + both(path, [[0.52, 1.445], [0.6, 1.445]], 'back', strip);
  g += both(path, [[0.089, 0.4], [0.089, 0.3]], 'front', strip);
  g += path([[-0.12, 1.1], [-0.05, 1.1]], 'front', strip) + path([[0.05, 1.1], [0.12, 1.1]], 'front', strip);
  g += both(path, [[0.05, 1.4], [0.05, 1.2]], 'back', strip);
  return svg(g, '#000');
}

/** Field coat: stitched panels and a closure, multiplied over the cloth colour. */
function coatPanels() {
  const seam = 'stroke="#000" stroke-opacity="0.5" stroke-width="2.2"';
  const piping = 'stroke="#fff" stroke-opacity="0.3" stroke-width="2.4"';
  let g = '';
  g += curve([[0.0, 1.47], [0.05, 1.3], [0.035, 1.0], [0.05, 0.74]], 'front', seam); // wrap closure
  g += curve([[0.012, 1.47], [0.062, 1.3], [0.047, 1.0], [0.062, 0.74]], 'front', piping);
  for (const side of ['front', 'back']) {
    g += path([[-0.22, 1.0], [0.22, 1.0]], side, seam) + path([[-0.22, 0.975], [0.22, 0.975]], side, piping); // belt line
    g += both(path, [[0.15, 1.42], [0.16, 0.76]], side, seam);
    g += path([[-0.2, 0.752], [0.2, 0.752]], side, piping); // hem
  }
  g += path([[0, 1.46], [0, 0.76]], 'back', seam);
  return svg(g, '#cfcfcf');
}

/** Living conduits grown into the Conductor's coat (teal on black). */
function coatGlow() {
  const vein = 'stroke="#7dffc4" stroke-width="3.2"';
  let g = '';
  g += both(curve, [[0.07, 1.44], [0.1, 1.3], [0.08, 1.14], [0.11, 1.02]], 'front', vein);
  g += both(curve, [[0.03, 1.42], [0.06, 1.25], [0.03, 1.1]], 'back', vein);
  g += both(curve, [[0.1, 0.96], [0.12, 0.86], [0.1, 0.78]], 'front', vein);
  return svg(g, '#000');
}

export const LOOK_TEXTURES = [
  { id: 'look_red_rucker_body', out: 'tex/look_red_rucker_body.webp', draw: redRuckerBody },
  { id: 'look_red_rucker_shorts', out: 'tex/look_red_rucker_shorts.webp', draw: redRuckerShorts },
  { id: 'look_plate_panels', out: 'tex/look_plate_panels.webp', draw: platePanels },
  { id: 'look_plate_glow', out: 'tex/look_plate_glow.webp', draw: plateGlow },
  { id: 'look_coat_panels', out: 'tex/look_coat_panels.webp', draw: coatPanels },
  { id: 'look_coat_glow', out: 'tex/look_coat_glow.webp', draw: coatGlow },
];

export async function renderLookTexture(spec, file) {
  await sharp(Buffer.from(spec.draw())).webp({ quality: 90, effort: 5 }).toFile(file);
}
